// Every number the city and the simulation agree on lives here once. Distances are metres,
// angles radians, times seconds. The plan is a 7x7 lattice of blocks sewn together by an
// 18 m road grid; the sea sits past the southern promenade.
const config = {
  seed: 1,
  grid: 7,
  pitch: 94,
  block: 76,
  road: 18,
  sidewalk: 6,
  curbWidth: 0.34,
  curbHeight: 0.18,
  slabHeight: 0.16,
  cityHalf: 329,
  beachStart: 338,
  beachEnd: 420,
  waterLevel: -1.05,
  worldSize: 1500,
  fog: { golden: 0.00215, night: 0.00135 },

  render: {
    width: 1280,
    height: 720,
    fov: 56,
    near: 0.28,
    far: 1600,
    exposureGolden: 1.0,
    exposureNight: 0.94,
    shadowMap: 2048,
    shadowExtent: 92,
  },

  player: {
