    const host = eastFront[0];
    plan.signs.push({
      x: host.x - host.w / 2 - 0.16,
      z: host.z,
      y: host.base + Math.min(host.h * 0.56, 7.6),
      yaw: -Math.PI / 2,
      w: 2.5,
      h: Math.min(9, host.h * 0.55),
      text: 'HOTEL SOL',
      vertical: true,
      color: 0xff9a76,
    });
    plan.signs.push({
      x: host.x - host.w / 2 - 0.16,
      z: host.z + host.h * 0.12,
      y: host.base + 3.6,
      yaw: -Math.PI / 2,
      w: 7.2,
      h: 1.7,
      text: 'CAFE VERANO',
      vertical: false,
      color: 0xffd08a,
    });
    plan.awnings.push({
      x: host.x - host.w / 2,
      z: host.z,
      y: host.base + 3.3,
      yaw: -Math.PI / 2,
      w: 9.4,
      d: 2.4,
      color: 0x2f7d72,
