  [232, 270, 308].forEach((x, index) => {
    plan.marina.piers.push({ x, z: 380, w: 5.4, d: 84, y: 0.42 });
    for (let i = 0; i < 3; i += 1) {
      plan.marina.boats.push({
        x: x + (i % 2 === 0 ? -6.2 : 6.2),
