  const element = document.createElement('canvas');
  element.width = width;
  element.height = height;
  return element;
}

function seeded(seed) {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
