    for (const item of [...boxes, ...stairHeads]) {
      dummy.position.set(item.x, item.y, item.z);
      dummy.rotation.set(0, 0, 0);
      dummy.scale.set(item.w, item.h, item.d);
      dummy.updateMatrix();
      boxesMesh.setMatrixAt(slot, dummy.matrix);
