    this.buildLamps();
    this.buildBenches();
    this.buildSmallFurniture();
    this.buildParkedCars();
    this.buildRocks();
    this.buildTrafficLights();
    this.buildPlanters();
    this.buildCafes();
    this.buildManholes();
    this.buildBlobShadows();
